static void SetBytes(unsigned int word, int isThumb, unsigned char * pBytes, int * pSize)
{
    if (isThumb && word < 0x10000)
    {
        pBytes[0] = (unsigned char)word;
        pBytes[1] = (unsigned char)(word >> 8);
        *pSize = 2;
        return;
    }
    if (isThumb)
        word = (word >> 16) | (word << 16);     // hw1 first in memory
    pBytes[0] = (unsigned char)word;
    pBytes[1] = (unsigned char)(word >> 8);
    pBytes[2] = (unsigned char)(word >> 16);
    pBytes[3] = (unsigned char)(word >> 24);
    *pSize = 4;
}

static int Decode(DianaContext * pContext, unsigned int word, DianaParserResult * pResult)
{
    unsigned char bytes[4];
    int size = 0;
    SetBytes(word, pContext->iArch == DIANA_ARCH_THUMB, bytes, &size);
    DianaMemoryStream stream;
    Diana_InitMemoryStream(&stream, bytes, size);
    return Diana_ParseCmd(pContext, Diana_GetRootLine(), &stream.parent.parent.parent, pResult);
}

static int DecodeA32(unsigned int word, DianaParserResult * pResult, const char * pProfile = 0)
{
    DianaContext context;
    Diana_InitContextEx(&context, DIANA_MODE32, DIANA_ARCH_ARM32);
    if (pProfile)
        Diana_SetArmProfile(&context, DianaArm_FindProfile(pProfile));
    return Decode(&context, word, pResult);
}

static int DecodeT32(unsigned int word, DianaParserResult * pResult)
{
    DianaContext context;
    Diana_InitContextEx(&context, DIANA_MODE32, DIANA_ARCH_THUMB);
    return Decode(&context, word, pResult);
}

// the rows are one stream: the T32 IT state goes from row to row
static void TestRows(const Arm32TextRow * pRows, size_t count, int arch)
{
    diana::CMasmString text;
    DianaContext context;
    Diana_InitContextEx(&context, DIANA_MODE32, arch);
    for (size_t i = 0; i < count; ++i)
    {
        DianaParserResult result;
        DIANA_TEST_ASSERT(Decode(&context, pRows[i].word, &result) == DI_SUCCESS);
        DIANA_TEST_ASSERT(result.iFullCmdSize == (arch == DIANA_ARCH_THUMB && pRows[i].word < 0x10000 ? 2 : 4));
        if (!pRows[i].pText)
            continue;
        const char * pText = text.Assign(&result, pRows[i].address);
        if (strcmp(pText, pRows[i].pText) != 0)
        {
            printf("%s: %08x: expected \"%s\", got \"%s\"\n", arch == DIANA_ARCH_THUMB ? "thumb" : "arm32",
                   pRows[i].word, pRows[i].pText, pText);
            DIANA_TEST_ASSERT(0);
        }
    }
}

static void test_arm32_text()
{
    TestRows(g_a32Rows, sizeof(g_a32Rows)/sizeof(g_a32Rows[0]), DIANA_ARCH_ARM32);
    TestRows(g_t32Rows, sizeof(g_t32Rows)/sizeof(g_t32Rows[0]), DIANA_ARCH_THUMB);
    TestRows(g_a32CuratedRows, sizeof(g_a32CuratedRows)/sizeof(g_a32CuratedRows[0]), DIANA_ARCH_ARM32);
    TestRows(g_t32CuratedRows, sizeof(g_t32CuratedRows)/sizeof(g_t32CuratedRows[0]), DIANA_ARCH_THUMB);
    TestRows(g_t32MoreRows, sizeof(g_t32MoreRows)/sizeof(g_t32MoreRows[0]), DIANA_ARCH_THUMB);
    TestRows(g_a32VfpRows, sizeof(g_a32VfpRows)/sizeof(g_a32VfpRows[0]), DIANA_ARCH_ARM32);
    TestRows(g_t32VfpRows, sizeof(g_t32VfpRows)/sizeof(g_t32VfpRows[0]), DIANA_ARCH_THUMB);
    TestRows(g_a32NeonRows, sizeof(g_a32NeonRows)/sizeof(g_a32NeonRows[0]), DIANA_ARCH_ARM32);
    TestRows(g_t32NeonRows, sizeof(g_t32NeonRows)/sizeof(g_t32NeonRows[0]), DIANA_ARCH_THUMB);
}

static void test_arm32_operands()
{
    DianaParserResult result;

    // addsne r0, r1, r2: the condition is in iPrefix, not an operand
    DIANA_TEST_ASSERT(DecodeA32(0x10910002, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "adds"));
    DIANA_TEST_ASSERT(DianaA32_GetCondition(&result) == 1);
    DIANA_TEST_ASSERT(result.iLinkedOpCount == 3);
    DIANA_TEST_ASSERT(result.linkedOperands[0].type == diana_register);
    DIANA_TEST_ASSERT(result.linkedOperands[0].value.recognizedRegister == reg_A32_R0);
    DIANA_TEST_ASSERT(result.linkedOperands[2].type == diana_arm_shifted_reg);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.recognizedRegister == reg_A32_R0 + 2);
    DIANA_TEST_ASSERT(result.linkedOperands[2].arm.shiftType == DIANA_ARM_SHIFT_NONE);

    // add r0, r0, #0x80000000: the rotated value, the rotation in shiftAmount
    DIANA_TEST_ASSERT(DecodeA32(0xe2800102, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA32_GetCondition(&result) == DIANA_A32_COND_AL);
    DIANA_TEST_ASSERT(result.linkedOperands[2].type == diana_imm);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.imm == 0x80000000u);
    DIANA_TEST_ASSERT(result.linkedOperands[2].arm.opKind == DIANA_A32_OPK_MODIMM);
    DIANA_TEST_ASSERT(result.linkedOperands[2].arm.shiftAmount == 2);

    // mov r0, r1, lsr #32 (DecodeImmShift: 0 is 32), mov r0, r1, ror r3
    DIANA_TEST_ASSERT(DecodeA32(0xe1a00021, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftType == DIANA_ARM_SHIFT_LSR);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftAmount == 32);
    DIANA_TEST_ASSERT(DecodeA32(0xe1a00371, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftType == DIANA_ARM_SHIFT_ROR);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.qualifier == DIANA_ARM_QUAL_SHIFT_REG);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftAmount == 3);
    DIANA_TEST_ASSERT(DecodeA32(0xe1a00061, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftType == DIANA_ARM_SHIFT_RRX);

    // ldr r0, [r1, #-4]!: a negative offset with writeback
    DIANA_TEST_ASSERT(DecodeA32(0xe5310004, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].type == diana_index);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.reg == reg_A32_R0 + 1);
    DIANA_TEST_ASSERT((long long)result.linkedOperands[1].value.rmIndex.dispValue == -4);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.qualifier == DIANA_ARM_QUAL_NEGATIVE);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.writeback == DIANA_ARM_WRITEBACK_PRE);
    // ldr r0, [r1], #4; ldr r0, [r1, -r2, lsl #2]; ldr r0, [pc, #8] (pc as the instruction reads it)
    DIANA_TEST_ASSERT(DecodeA32(0xe4910004, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.writeback == DIANA_ARM_WRITEBACK_POST);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.dispValue == 4);
    DIANA_TEST_ASSERT(DecodeA32(0xe7110102, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.indexed_reg == reg_A32_R0 + 2);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.qualifier == DIANA_ARM_QUAL_NEGATIVE);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftType == DIANA_ARM_SHIFT_LSL);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftAmount == 2);
    DIANA_TEST_ASSERT(DecodeA32(0xe59f0008, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.reg == reg_A32_PC);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.dispValue == 8);

    // push {r4, lr}: a register mask, sp! is a register with writeback
    DIANA_TEST_ASSERT(DecodeA32(0xe92d4010, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].value.recognizedRegister == reg_A32_SP);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.writeback == DIANA_ARM_WRITEBACK_PRE);
    DIANA_TEST_ASSERT(result.linkedOperands[1].type == diana_arm_regmask);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.imm == 0x4010);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.regCount == 2);

    // b: relative to the next instruction like x86 and A64 (A32 reads the PC as the address + 8)
    DIANA_TEST_ASSERT(DecodeA32(0xeafffffe, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].type == diana_rel);
    DIANA_TEST_ASSERT((long long)result.linkedOperands[0].value.rel.m_value == -4);
    DIANA_TEST_ASSERT(result.pInfo->m_pGroupInfo->m_pLinkedInfo != 0);

    // T32: push {r4, lr} with the extra bit, bl with the J bits, blx to A32 from an aligned base
    DIANA_TEST_ASSERT(DecodeT32(0xb510, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iFullCmdSize == 2);
    DIANA_TEST_ASSERT(result.linkedOperands[0].value.imm == 0x4010);
    DIANA_TEST_ASSERT(DecodeT32(0xf7fffffe, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iFullCmdSize == 4);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "bl"));
    DIANA_TEST_ASSERT((long long)result.linkedOperands[0].value.rel.m_value == -4);
    DIANA_TEST_ASSERT(DecodeT32(0xf000e800, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "blx"));
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.qualifier == DIANA_ARM_QUAL_ALIGN_PC);
    // add.w r0, r1, #0xab00ab00: ThumbExpandImm
    DIANA_TEST_ASSERT(DecodeT32(0xf10120ab, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.imm == 0xab00ab00u);
    // cbnz r1, <+2>: unsigned
    DIANA_TEST_ASSERT(DecodeT32(0xbbf9, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rel.m_value == 0x7e + 4 - 2);
}

// the T32 IT state: the condition comes from the block, the context moves to the next instruction
static void test_arm32_it()
{
    DianaContext context;
    DianaParserResult result;
    Diana_InitContextEx(&context, DIANA_MODE32, DIANA_ARCH_THUMB);

    DIANA_TEST_ASSERT(Decode(&context, 0xbf0c, &result) == DI_SUCCESS);    // ite eq
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "it"));
    DIANA_TEST_ASSERT(DianaA32_GetCondition(&result) == DIANA_A32_COND_AL);
    DIANA_TEST_ASSERT((context.iArmFlags & 0xFF) == 0x0C);
    DIANA_TEST_ASSERT(Decode(&context, 0x1888, &result) == DI_SUCCESS);    // addeq
    DIANA_TEST_ASSERT(DianaA32_GetCondition(&result) == 0);
    DIANA_TEST_ASSERT((result.iPrefix & (DIANA_A32_PREFIX_IN_IT | DIANA_A32_PREFIX_NOT_LAST)) ==
                      (DIANA_A32_PREFIX_IN_IT | DIANA_A32_PREFIX_NOT_LAST));
    DIANA_TEST_ASSERT(Decode(&context, 0x1888, &result) == DI_SUCCESS);    // addne, the last one
    DIANA_TEST_ASSERT(DianaA32_GetCondition(&result) == 1);
    DIANA_TEST_ASSERT((result.iPrefix & (DIANA_A32_PREFIX_IN_IT | DIANA_A32_PREFIX_NOT_LAST)) == DIANA_A32_PREFIX_IN_IT);
    DIANA_TEST_ASSERT(((result.iPrefix >> DIANA_A32_PREFIX_IT_SHIFT) & 15) == 1);
    DIANA_TEST_ASSERT(Decode(&context, 0x1888, &result) == DI_SUCCESS);    // adds, after the block
    DIANA_TEST_ASSERT(DianaA32_GetCondition(&result) == DIANA_A32_COND_AL);
    DIANA_TEST_ASSERT(!(result.iPrefix & DIANA_A32_PREFIX_IN_IT));

    // a new stream starts outside any block
    DIANA_TEST_ASSERT(Decode(&context, 0xbf08, &result) == DI_SUCCESS);    // it eq
    DianaA32_ResetItState(&context);
    DIANA_TEST_ASSERT(Decode(&context, 0x1888, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA32_GetCondition(&result) == DIANA_A32_COND_AL);

    // the decode functions without a stream: a 16-bit instruction doesn't use hw2
    DIANA_TEST_ASSERT(DianaA32_DecodeT32(&context, 0x4770, 0xffff, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iFullCmdSize == 2 && !strcmp(result.pInfo->m_pGroupInfo->m_pName, "bx"));
    DIANA_TEST_ASSERT(DianaA32_DecodeA32(&context, 0xe12fff1e, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iFullCmdSize == 4 && !strcmp(result.pInfo->m_pGroupInfo->m_pName, "bx"));

    DIANA_TEST_ASSERT(DianaA32_GetT32Size(0x4770) == 2);
    DIANA_TEST_ASSERT(DianaA32_GetT32Size(0xe7fe) == 2);
    DIANA_TEST_ASSERT(DianaA32_GetT32Size(0xe800) == 4);
    DIANA_TEST_ASSERT(DianaA32_GetT32Size(0xf000) == 4);
    DIANA_TEST_ASSERT(DianaA32_GetT32Size(0xffff) == 4);
}

static void test_arm32_stream()
{
    // T32 16-bit and 32-bit instructions in one buffer, then a half instruction at the end
    unsigned char code[] = {0x10, 0xb5, 0x00, 0xf0, 0x00, 0xf8, 0x70, 0x47, 0x00, 0xf0};
    DianaMemoryStream stream;
    DianaContext context;
    DianaParserResult result;
    Diana_InitContextEx(&context, DIANA_MODE32, DIANA_ARCH_THUMB);
    Diana_InitMemoryStream(&stream, code, sizeof(code));
    DIANA_TEST_ASSERT(Diana_ParseCmd(&context, Diana_GetRootLine(), &stream.parent.parent.parent, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iFullCmdSize == 2 && !strcmp(result.pInfo->m_pGroupInfo->m_pName, "push"));
    DIANA_TEST_ASSERT(Diana_ParseCmd(&context, Diana_GetRootLine(), &stream.parent.parent.parent, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iFullCmdSize == 4 && !strcmp(result.pInfo->m_pGroupInfo->m_pName, "bl"));
    DIANA_TEST_ASSERT(result.bytesCount == 4 && result.bytes[0] == 0x00 && result.bytes[1] == 0xf0);
    DIANA_TEST_ASSERT(Diana_ParseCmd(&context, Diana_GetRootLine(), &stream.parent.parent.parent, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iFullCmdSize == 2 && !strcmp(result.pInfo->m_pGroupInfo->m_pName, "bx"));
    DIANA_TEST_ASSERT(Diana_ParseCmd(&context, Diana_GetRootLine(), &stream.parent.parent.parent, &result) == DI_END_OF_STREAM);
    DIANA_TEST_ASSERT(Diana_ParseCmd(&context, Diana_GetRootLine(), &stream.parent.parent.parent, &result) == DI_END);

    // A32: a short word
    unsigned char word[] = {0x1e, 0xff, 0x2f};
    Diana_InitContextEx(&context, DIANA_MODE32, DIANA_ARCH_ARM32);
    Diana_InitMemoryStream(&stream, word, sizeof(word));
    DIANA_TEST_ASSERT(Diana_ParseCmd(&context, Diana_GetRootLine(), &stream.parent.parent.parent, &result) == DI_END_OF_STREAM);
    DIANA_TEST_ASSERT(result.iFullCmdSize == 3);
}

static void test_arm32_word_classes()
{
    DianaParserResult result;
    DIANA_TEST_ASSERT(DecodeA32(0xe0810002, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA32_GetWordClass(&result) == DIANA_A64_WORD_SUPPORTED);
    DIANA_TEST_ASSERT(DianaA32_GetCmdInfo(&result) != 0);
    DIANA_TEST_ASSERT(DianaA64_GetCmdInfo(&result) == 0);
    DIANA_TEST_ASSERT(DianaA64_GetWordClass(&result) == -1);
    DIANA_TEST_ASSERT(DecodeA32(0xffffffff, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA32_GetWordClass(&result) == DIANA_A64_WORD_UNALLOCATED);
    DIANA_TEST_ASSERT(result.iFullCmdSize == 4);
    DIANA_TEST_ASSERT(DecodeT32(0xb800, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA32_GetWordClass(&result) == DIANA_A64_WORD_UNALLOCATED);
    DIANA_TEST_ASSERT(result.iFullCmdSize == 2);
    DIANA_TEST_ASSERT(DecodeT32(0xe800e800, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA32_GetWordClass(&result) == DIANA_A64_WORD_UNALLOCATED);
    DIANA_TEST_ASSERT(result.iFullCmdSize == 4);

    // Diana_GetGroupInfo knows the AArch32 ids
    DIANA_TEST_ASSERT(Diana_GetGroupInfo(diana_a32_cmd_add) != 0);
    DIANA_TEST_ASSERT(!strcmp(Diana_GetGroupInfo(diana_a32_cmd_add)->m_pName, "add"));
    DIANA_TEST_ASSERT(Diana_GetGroupInfo(diana_a32_cmd_end) == 0);
    DIANA_TEST_ASSERT(DIANA_CMD_SET(diana_a32_cmd_add) == DIANA_CMD_SET_A32);
}

static void test_arm32_profiles()
{
    DianaContext context;
    // the feature set follows the architecture of the context
    Diana_InitContextEx(&context, DIANA_MODE32, DIANA_ARCH_ARM32);
    DIANA_TEST_ASSERT(context.armFeatures == DIANA_A32_FEATURE_ALL);
    Diana_SetArmProfile(&context, DianaArm_FindProfile("all"));
    DIANA_TEST_ASSERT(context.armFeatures == DIANA_A32_FEATURE_ALL);
    Diana_InitContextEx(&context, DIANA_MODE64, DIANA_ARCH_AARCH64);
    DIANA_TEST_ASSERT(context.armFeatures == DIANA_A64_FEATURE_ALL);
    Diana_SetArmProfile(&context, DianaArm_FindProfile("all"));
    DIANA_TEST_ASSERT(context.armFeatures == DIANA_A64_FEATURE_ALL);
    {
        int count = 0;
        const DianaArmProfile * pProfiles = DianaArm_GetProfiles(&count);
        DIANA_TEST_ASSERT(pProfiles[0].a32Features == DIANA_A32_FEATURE_ALL);
    }
    // a profile without the base set: every instruction is disabled, not unallocated
    {
        DianaParserResult result;
        static const DianaArmProfile none = {"none", "", 0, 0};
        Diana_InitContextEx(&context, DIANA_MODE32, DIANA_ARCH_ARM32);
        Diana_SetArmProfile(&context, &none);
        DIANA_TEST_ASSERT(Decode(&context, 0xe0810002, &result) == DI_SUCCESS);
        DIANA_TEST_ASSERT(DianaA32_GetWordClass(&result) == DIANA_A64_WORD_DISABLED);
        DIANA_TEST_ASSERT(Decode(&context, 0xffffffff, &result) == DI_SUCCESS);
        DIANA_TEST_ASSERT(DianaA32_GetWordClass(&result) == DIANA_A64_WORD_UNALLOCATED);
    }
}

// M6 step 6: the AArch32 versions of the profiles
static int ClassWith(const char * pProfile, int arch, unsigned int word, const char * pName = 0)
{
    DianaContext context;
    DianaParserResult result;
    Diana_InitContextEx(&context, DIANA_MODE32, arch);
    Diana_SetArmProfile(&context, DianaArm_FindProfile(pProfile));
    if (Decode(&context, word, &result) != DI_SUCCESS)
        return -1;
    if (pName && DianaA32_GetWordClass(&result) == DIANA_A64_WORD_SUPPORTED && strcmp(result.pInfo->m_pGroupInfo->m_pName, pName))
        return -2;
    return DianaA32_GetWordClass(&result);
}

static void test_arm32_versions()
{
    const int supported = DIANA_A64_WORD_SUPPORTED, disabled = DIANA_A64_WORD_DISABLED;
    // movw r0, #0x1234 is ARMv6T2: the Raspberry Pi 1 (ARMv6K) has it not, ARMv7 has
    DIANA_TEST_ASSERT(ClassWith("rpi1", DIANA_ARCH_ARM32, 0xe3010234) == disabled);
    DIANA_TEST_ASSERT(ClassWith("armv7", DIANA_ARCH_ARM32, 0xe3010234, "mov") == supported);
    // clrex is ARMv6K: armv6 has it not, rpi1 has
    DIANA_TEST_ASSERT(ClassWith("armv6", DIANA_ARCH_ARM32, 0xf57ff01f) == disabled);
    DIANA_TEST_ASSERT(ClassWith("rpi1", DIANA_ARCH_ARM32, 0xf57ff01f, "clrex") == supported);
    // every 32-bit T32 instruction but BL is ARMv6T2; the 16-bit set is ARMv6
    DIANA_TEST_ASSERT(ClassWith("rpi1", DIANA_ARCH_THUMB, 0xf1010001) == disabled);     // add.w r0, r1, #1
    DIANA_TEST_ASSERT(ClassWith("rpi1", DIANA_ARCH_THUMB, 0xf000f800, "bl") == supported);
    DIANA_TEST_ASSERT(ClassWith("rpi1", DIANA_ARCH_THUMB, 0x1888, "add") == supported);
    // sdiv is ARMv7VE: Cortex-A8 (armv7) has it not, the Cortex-A7 of the Pi 2 has
    DIANA_TEST_ASSERT(ClassWith("armv7", DIANA_ARCH_ARM32, 0xe710f211) == disabled);
    DIANA_TEST_ASSERT(ClassWith("rpi2", DIANA_ARCH_ARM32, 0xe710f211, "sdiv") == supported);
    // VFPv2 has no vmov immediate (VFPv3) and no vfma (VFPv4)
    DIANA_TEST_ASSERT(ClassWith("rpi1", DIANA_ARCH_ARM32, 0xeeb70a00) == disabled);
    DIANA_TEST_ASSERT(ClassWith("armv7", DIANA_ARCH_ARM32, 0xeeb70a00, "vmov") == supported);
    DIANA_TEST_ASSERT(ClassWith("armv7", DIANA_ARCH_ARM32, 0xeea00a81) == disabled);
    DIANA_TEST_ASSERT(ClassWith("rpi2", DIANA_ARCH_ARM32, 0xeea00a81, "vfma") == supported);
    // ARMv8: lda, vrinta; no swp and no generic coprocessor instructions any more
    DIANA_TEST_ASSERT(ClassWith("rpi2", DIANA_ARCH_ARM32, 0xe1910c9f) == disabled);    // lda r0, [r1]
    DIANA_TEST_ASSERT(ClassWith("rpi3", DIANA_ARCH_ARM32, 0xe1910c9f, "lda") == supported);
    DIANA_TEST_ASSERT(ClassWith("rpi1", DIANA_ARCH_ARM32, 0xe1020091, "swp") == supported);   // swp r0, r1, [r2]
    DIANA_TEST_ASSERT(ClassWith("rpi3", DIANA_ARCH_ARM32, 0xe1020091) != supported);
    DIANA_TEST_ASSERT(ClassWith("rpi2", DIANA_ARCH_ARM32, 0xee123366, "cdp") == supported);
    DIANA_TEST_ASSERT(ClassWith("rpi3", DIANA_ARCH_ARM32, 0xee123366) == disabled);
    // a hint the profile has not is a NOP hint: tsb csync without FEAT_TRF
    DIANA_TEST_ASSERT(ClassWith("rpi2", DIANA_ARCH_THUMB, 0xf3af8012, "nop") == supported);
    DIANA_TEST_ASSERT(ClassWith("all", DIANA_ARCH_THUMB, 0xf3af8012, "tsb") == supported);
    // the cp8 forms of ARMv7 are VCMLA with FEAT_FCMA: the ARMv7 profile decodes cdp2
    DIANA_TEST_ASSERT(ClassWith("armv7", DIANA_ARCH_ARM32, 0xfe19482b, "cdp2") == supported);
    DIANA_TEST_ASSERT(ClassWith("all", DIANA_ARCH_ARM32, 0xfe19482b, "vcmla") == supported);
    // CPUs without AArch32 (Apple M1) disable all of it; AArch32-only CPUs have no A64
    DIANA_TEST_ASSERT(ClassWith("apple-m1", DIANA_ARCH_ARM32, 0xe0810002) == disabled);
    DIANA_TEST_ASSERT(DianaArm_FindProfile("rpi2")->features == 0);
    DIANA_TEST_ASSERT(DianaArm_FindProfile("armv8.0")->a32Features & DIANA_A32_FEATURE_V8);
}

static void test_arm32_abi()
{
    DIANA_TEST_ASSERT(diana_arm_regmask == 13);
    DIANA_TEST_ASSERT(DIANA_ARM_SHIFT_RRX == 16);
    DIANA_TEST_ASSERT(DIANA_ARM_QUAL_NEGATIVE == 5 && DIANA_ARM_QUAL_SHIFT_REG == 6 && DIANA_ARM_QUAL_ALIGN_PC == 7);
    DIANA_TEST_ASSERT(reg_A32_R0 == 0x600 && reg_A32_SP == 0x60D && reg_A32_LR == 0x60E && reg_A32_PC == 0x60F);
    DIANA_TEST_ASSERT(reg_A32_S0 == 0x620 && reg_A32_D0 == 0x640 && reg_A32_Q0 == 0x660 && reg_A32_APSR == 0x670);
    DIANA_TEST_ASSERT(DIANA_A32_CMD_BASE == 0x20000 && diana_a32_cmd_inst == DIANA_A32_CMD_BASE);
    DIANA_TEST_ASSERT(offsetof(DianaArmProfile, a32Features) == offsetof(DianaArmProfile, features) + 8);
}

// M6 step 2: the operands of the whole A32 set
static void test_arm32_a32_operands()
{
    DianaParserResult result;

    // ldrd r0, r1, [r1]: Rt2 is Rt + 1
    DIANA_TEST_ASSERT(DecodeA32(0xe1c100d0, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iLinkedOpCount == 3);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.recognizedRegister == reg_A32_R0 + 1);
    // ssat r0, #8, r1, lsl #3: sat_imm + 1; usat r1, #0, r5, asr #0 is asr #32
    DIANA_TEST_ASSERT(DecodeA32(0xe6a70191, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.imm == 8);
    DIANA_TEST_ASSERT(result.linkedOperands[2].arm.shiftType == DIANA_ARM_SHIFT_LSL && result.linkedOperands[2].arm.shiftAmount == 3);
    DIANA_TEST_ASSERT(DecodeA32(0xe6e01055, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.imm == 0);
    DIANA_TEST_ASSERT(result.linkedOperands[2].arm.shiftType == DIANA_ARM_SHIFT_ASR && result.linkedOperands[2].arm.shiftAmount == 32);
    // bfi r0, r1, #4, #5: the width from msb and lsb
    DIANA_TEST_ASSERT(DecodeA32(0xe7c80211, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.imm == 4);
    DIANA_TEST_ASSERT(result.linkedOperands[3].arm.opKind == DIANA_A32_OPK_BFWIDTH && result.linkedOperands[3].value.imm == 5);
    // sxtb r0, r1, ror #8; uxtb r0, r1 (rotation 0 is no shift); pkhtb r0, r1, r2, asr #32
    DIANA_TEST_ASSERT(DecodeA32(0xe6af0471, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftType == DIANA_ARM_SHIFT_ROR && result.linkedOperands[1].arm.shiftAmount == 8);
    DIANA_TEST_ASSERT(DecodeA32(0xe6ef0071, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftType == DIANA_ARM_SHIFT_NONE);
    DIANA_TEST_ASSERT(DecodeA32(0xe6810052, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[2].arm.shiftType == DIANA_ARM_SHIFT_ASR && result.linkedOperands[2].arm.shiftAmount == 32);

    // mcr 15, 0, r0, cr7, cr10, {4}: the coprocessor from the cp15 bit, registers and opcodes
    DIANA_TEST_ASSERT(DecodeA32(0xee070f9a, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iLinkedOpCount == 6);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.opKind == DIANA_A32_OPK_COPROC && result.linkedOperands[0].value.imm == 15);
    DIANA_TEST_ASSERT(result.linkedOperands[0].type == diana_arm_special);
    DIANA_TEST_ASSERT(result.linkedOperands[3].arm.opKind == DIANA_A32_OPK_CREG && result.linkedOperands[3].value.imm == 7);
    DIANA_TEST_ASSERT(result.linkedOperands[4].value.imm == 10 && result.linkedOperands[5].value.imm == 4);
    // ldc 14, cr5, [pc, #16]: the fixed p14 and c5 of ARMv8, the offset times 4
    DIANA_TEST_ASSERT(DecodeA32(0xed9f5e04, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].value.imm == 14 && result.linkedOperands[1].value.imm == 5);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.rmIndex.reg == reg_A32_PC && result.linkedOperands[2].value.rmIndex.dispValue == 16);
    // the ARMv7 generic form: cdp 3, 1, cr3, cr2, cr6, {3}
    DIANA_TEST_ASSERT(DecodeA32(0xee123366, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "cdp") && result.linkedOperands[0].value.imm == 3);

    // MRS/MSR: SYSm as objdump numbers it, the PSR mask
    DIANA_TEST_ASSERT(DecodeA32(0xe10f0000, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.opKind == DIANA_A32_OPK_SYSM && result.linkedOperands[1].value.imm == 15);
    DIANA_TEST_ASSERT(DecodeA32(0xe1000200, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.imm == 32);
    DIANA_TEST_ASSERT(DecodeA32(0xe329f01f, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.opKind == DIANA_A32_OPK_PSRMASK && result.linkedOperands[0].value.imm == 9);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.opKind == DIANA_A32_OPK_MODIMM && result.linkedOperands[1].value.imm == 31);
    // dmb ish, cpsid i, setend be
    DIANA_TEST_ASSERT(DecodeA32(0xf57ff05b, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.opKind == DIANA_A32_OPK_BARRIER && result.linkedOperands[0].value.imm == 11);
    DIANA_TEST_ASSERT(DianaA32_GetCondition(&result) == DIANA_A32_COND_AL);
    DIANA_TEST_ASSERT(DecodeA32(0xf10c0080, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.opKind == DIANA_A32_OPK_IFLAGS && result.linkedOperands[0].value.imm == 2);
    DIANA_TEST_ASSERT(DecodeA32(0xf1010200, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.opKind == DIANA_A32_OPK_ENDIAN && result.linkedOperands[0].value.imm == 1);

    // adr: sub r0, pc, #8 points at the instruction itself, relative to the next one like a branch
    DIANA_TEST_ASSERT(DecodeA32(0xe24f0008, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "adr"));
    DIANA_TEST_ASSERT(result.linkedOperands[1].type == diana_rel && (long long)result.linkedOperands[1].value.rel.m_value == -4);
    DIANA_TEST_ASSERT(DecodeA32(0xe28f0f01, &result) == DI_SUCCESS);       // add r0, pc, #4
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rel.m_value == 8);
    // ldm sp!, {r0, pc}^: pc is always in the list of the exception return, ^ is the qualifier
    DIANA_TEST_ASSERT(DecodeA32(0xe8fd8001, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.imm == 0x8001);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.qualifier == DIANA_ARM_QUAL_USER);
    // ldm/stm addressing modes are groups: ldmdb, stmib
    DIANA_TEST_ASSERT(DecodeA32(0xe9100006, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "ldmdb"));
    DIANA_TEST_ASSERT(DecodeA32(0xe9800006, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "stmib"));

    // bkpt and crc32 need cond 1110: the other conditions are UNPREDICTABLE, undefined words here (M6 step 7: AArch32
    // has no unsupported words any more)
    DIANA_TEST_ASSERT(DecodeA32(0xe1200070, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "bkpt"));
    DIANA_TEST_ASSERT(DecodeA32(0x01000040, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA32_GetWordClass(&result) == DIANA_A64_WORD_UNALLOCATED);
    // a should-be-zero bit set: not the instruction (mvn with Rn = 4)
    DIANA_TEST_ASSERT(DecodeA32(0xe3f44c52, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(DianaA32_GetWordClass(&result) == DIANA_A64_WORD_UNALLOCATED);
}

// M6 step 4: VFP operands
static void test_arm32_vfp_operands()
{
    DianaParserResult result;
    const DianaA32Tables * pTables = DianaA32_GetTables();

    // vaddeq.f64 d0, d1, d17: D registers from D:Vd, the data type is the command's suffix
    DIANA_TEST_ASSERT(DecodeA32(0x0e310b21, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "vadd") && DianaA32_GetCondition(&result) == 0);
    DIANA_TEST_ASSERT(!strcmp(pTables->pSuffixes[DianaA32_GetCmdInfo(&result)->suffix], ".f64"));
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.opKind == DIANA_A32_OPK_DREG && result.linkedOperands[0].type == diana_register);
    DIANA_TEST_ASSERT(result.linkedOperands[0].value.recognizedRegister == reg_A32_D0);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.recognizedRegister == reg_A32_D0 + 17);
    DIANA_TEST_ASSERT(result.linkedOperands[0].usedSize == 8);
    // vadd.f32 s0, s1, s2: S registers from Vd:D
    DIANA_TEST_ASSERT(DecodeA32(0xee300a81, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.recognizedRegister == reg_A32_S0 + 1);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.recognizedRegister == reg_A32_S0 + 2);
    // vmov immediate: VFPExpandImm to the bits of the size; vcmp #0.0 is 0
    DIANA_TEST_ASSERT(DecodeA32(0xeeb70a00, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.opKind == DIANA_A32_OPK_FPIMM && result.linkedOperands[1].value.imm == 0x3f800000);
    DIANA_TEST_ASSERT(DecodeA32(0xeeb80b04, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.imm == 0xc004000000000000ULL && result.linkedOperands[1].usedSize == 8);
    DIANA_TEST_ASSERT(DecodeA32(0xeeb70900, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.imm == 0x3c00);
    DIANA_TEST_ASSERT(DecodeA32(0xeeb50a40, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.opKind == DIANA_A32_OPK_FPIMM && result.linkedOperands[1].value.imm == 0);
    // vcvt.f32.s32 s0, s0, #16: 32 - imm4:i
    DIANA_TEST_ASSERT(DecodeA32(0xeeba0ac8, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[2].arm.opKind == DIANA_A32_OPK_FBITS && result.linkedOperands[2].value.imm == 16);
    // vmov r0, r1, s0, s1: the second S register is the next one
    DIANA_TEST_ASSERT(DecodeA32(0xec510a10, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.iLinkedOpCount == 4 && result.linkedOperands[3].value.recognizedRegister == reg_A32_S0 + 1);
    // vpush {d8-d15}, vpop {s16-s17}: the first register and the count
    DIANA_TEST_ASSERT(DecodeA32(0xed2d8b10, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].type == diana_arm_reglist);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.recognizedRegister == reg_A32_D0 + 8 && result.linkedOperands[1].arm.regCount == 8);
    DIANA_TEST_ASSERT(DecodeA32(0xecbd8a02, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.recognizedRegister == reg_A32_S0 + 16 && result.linkedOperands[1].arm.regCount == 2);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.writeback == DIANA_ARM_WRITEBACK_PRE);
    // vldr d0, [pc, #16]: the literal; vmrs r0, fpscr
    DIANA_TEST_ASSERT(DecodeA32(0xed9f0b04, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.reg == reg_A32_PC && result.linkedOperands[1].value.rmIndex.dispValue == 16);
    DIANA_TEST_ASSERT(DecodeA32(0xeef10a10, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.opKind == DIANA_A32_OPK_FPSYSREG && result.linkedOperands[1].value.imm == 1);
    // T32: the same encoding with hw1 1110, the condition from the IT block; mrc of the TLS register
    DIANA_TEST_ASSERT(DecodeT32(0xee300a81, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "vadd") && result.iFullCmdSize == 4);
    DIANA_TEST_ASSERT(DecodeT32(0xee1d0f70, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(result.pInfo->m_pGroupInfo->m_pName, "mrc") && result.linkedOperands[0].value.imm == 15);
}

// M6 step 5: Advanced SIMD operands
static void test_arm32_neon_operands()
{
    DianaParserResult result;

    // vadd.i32 q0, q1, q8: Q registers are (D:Vd) / 2; an odd Vd is UNDEFINED
    DIANA_TEST_ASSERT(DecodeA32(0xf2220860, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.opKind == DIANA_A32_OPK_QREG);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.recognizedRegister == reg_A32_Q0 + 8 && result.linkedOperands[2].usedSize == 16);
    DIANA_TEST_ASSERT(DecodeA32(0xf2221860, &result) == DI_SUCCESS);       // Vd = 0001
    DIANA_TEST_ASSERT(DianaA32_GetWordClass(&result) == DIANA_A64_WORD_UNALLOCATED);
    // vmul.i16 q0, q1, d7[3]: a 16-bit scalar is d0..d7, the index M:Vm<3>
    DIANA_TEST_ASSERT(DecodeA32(0xf392086f, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[2].arm.opKind == DIANA_A32_OPK_DSCALAR);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.recognizedRegister == reg_A32_D0 + 7 && result.linkedOperands[2].arm.lane == 3);
    DIANA_TEST_ASSERT(result.linkedOperands[2].arm.arrangement == DIANA_ARM_ARR_H);
    // vshr.s8 d0, d1, #8 (16 - imm6), vshl.i32 d0, d1, #31 (imm6 - 32)
    DIANA_TEST_ASSERT(DecodeA32(0xf2880011, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.imm == 8);
    DIANA_TEST_ASSERT(DecodeA32(0xf2bf0511, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.imm == 31);
    // AdvSIMDExpandImm: vmov.i32 d0, #0x00ff0000, vmov.i64 d0, #0xff00ff00ff00ff00, vmov.f32 q0, #1.0
    DIANA_TEST_ASSERT(DecodeA32(0xf387041f, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.opKind == DIANA_A32_OPK_NEONIMM);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.imm == 0x00ff000000ff0000ULL);
    DIANA_TEST_ASSERT(DecodeA32(0xf3820e3a, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.imm == 0xff00ff00ff00ff00ULL);
    DIANA_TEST_ASSERT(DecodeA32(0xf2870f50, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.imm == 0x3f8000003f800000ULL);
    // vld1.16 {d0-d1}, [r0 :128]!: two registers, 16 bytes aligned, writeback
    DIANA_TEST_ASSERT(DecodeA32(0xf4200a6d, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].type == diana_arm_reglist && result.linkedOperands[0].arm.regCount == 2);
    DIANA_TEST_ASSERT(result.linkedOperands[1].type == diana_index && result.linkedOperands[1].arm.shiftAmount == 16);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.writeback == DIANA_ARM_WRITEBACK_POST);
    // vld2.8 {d0,d2}, [r1]: spacing 2; vld1.32 {d0-d3}, [r0], r2: post-index by a register
    DIANA_TEST_ASSERT(DecodeA32(0xf421090f, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.regCount == 2 && result.linkedOperands[0].arm.regStride == 2);
    DIANA_TEST_ASSERT(DecodeA32(0xf4200282, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.rmIndex.indexed_reg == reg_A32_R0 + 2);
    // vld2.16 {d0[2],d2[2]}, [r0]: one lane; vld4.8 {d0[]-d3[]}, [r0 :32]!: all lanes
    DIANA_TEST_ASSERT(DecodeA32(0xf4a005af, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.lane == 2 && result.linkedOperands[0].arm.regStride == 2);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.arrangement == DIANA_ARM_ARR_H);
    DIANA_TEST_ASSERT(DecodeA32(0xf4a00f1d, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[0].arm.qualifier == DIANA_ARM_QUAL_ALL_LANES && result.linkedOperands[0].arm.regCount == 4);
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.shiftAmount == 4);
    // vtbl.8 d0, {d1-d3}, d4: len + 1 registers
    DIANA_TEST_ASSERT(DecodeA32(0xf3b10a04, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[1].value.recognizedRegister == reg_A32_D0 + 1 && result.linkedOperands[1].arm.regCount == 3);
    // vmov.u8 r0, d1[7]: an element move, the type is the suffix
    DIANA_TEST_ASSERT(DecodeA32(0xeef10b70, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(!strcmp(DianaA32_GetTables()->pSuffixes[DianaA32_GetCmdInfo(&result)->suffix], ".u8"));
    DIANA_TEST_ASSERT(result.linkedOperands[1].arm.lane == 7);
    // vcmla.f16 d4, d9, d11[1], #90: the rotation
    DIANA_TEST_ASSERT(DecodeA32(0xfe19482b, &result) == DI_SUCCESS);
    DIANA_TEST_ASSERT(result.linkedOperands[3].arm.opKind == DIANA_A32_OPK_ROTATE && result.linkedOperands[3].value.imm == 90);
    DIANA_TEST_ASSERT(result.linkedOperands[2].value.recognizedRegister == reg_A32_D0 + 11);
}

void test_arm32()
{
    DIANA_TEST(test_arm32_text());
    DIANA_TEST(test_arm32_operands());
    DIANA_TEST(test_arm32_a32_operands());
    DIANA_TEST(test_arm32_vfp_operands());
    DIANA_TEST(test_arm32_neon_operands());
    DIANA_TEST(test_arm32_it());
    DIANA_TEST(test_arm32_stream());
    DIANA_TEST(test_arm32_word_classes());
    DIANA_TEST(test_arm32_profiles());
    DIANA_TEST(test_arm32_versions());
    DIANA_TEST(test_arm32_abi());
}
